param([string]$SavePath=(Join-Path $PSScriptRoot '../../.local-research/runtime/profile-20261102/Saves/logistics-final.rws'))
# Read only; uses original-game XML, never loads/executed game code or changes saves.
$ErrorActionPreference='Stop'
$s=[xml](Get-Content -Raw -LiteralPath $SavePath)
$zones=@($s.SelectNodes('//zoneManager/allZones/li')|ForEach-Object{[ordered]@{id=[int]$_.ID;class=$_.GetAttribute('Class');label=[string]$_.label;cells=@($_.SelectNodes('cells/li')|ForEach-Object{$_.InnerText});priority=[string]$_.settings.priority;allowed_defs=@($_.SelectNodes('settings/filter/allowedDefs/li')|ForEach-Object{$_.InnerText})}})
$wood=@($s.SelectNodes('//thing[def="WoodLog"]')|ForEach-Object{[ordered]@{id=[string]$_.id;pos=[string]$_.pos;count=[int]$_.stackCount;health=[int]$_.health;spawned_tick=[int]$_.spawnedTick;forbidden=([string]$_.forbidden -eq 'True')}}|Sort-Object {$_.id})
$pawns=@($s.SelectNodes('//thing[def="Human"]')|ForEach-Object{[ordered]@{id=[string]$_.id;nick=[string]$_.name.nick;pos=[string]$_.pos;job=[string]$_.jobs.curJob.def;job_id=[string]$_.jobs.curJob.loadID;job_target=[string]$_.jobs.curJob.targetA;job_started=[int]$_.jobs.curJob.startTick;asleep=([string]$_.jobs.curDriver.asleep -eq 'True');carry=@($_.SelectNodes('carryTracker/innerContainer/innerList/li')|ForEach-Object{[ordered]@{id=[string]$_.id;def=[string]$_.def;count=[int]$_.stackCount}})}})
$reservations=@($s.SelectNodes('//reservationManager/reservations/li[starts-with(claimant,"Thing_Human")]')|ForEach-Object{[ordered]@{claimant=[string]$_.claimant;job=[string]$_.job;target=[string]$_.target;max_pawns=[int]$_.maxPawns;stack_count=[int]$_.stackCount}})
[ordered]@{file=(Split-Path -Leaf $SavePath);sha256=(Get-FileHash -LiteralPath $SavePath -Algorithm SHA256).Hash.ToLowerInvariant();bytes=(Get-Item -LiteralPath $SavePath).Length;version=$s.SelectSingleNode('//meta/gameVersion').InnerText;mods=@($s.SelectNodes('//meta/modIds/li')|ForEach-Object{$_.InnerText});tick=[int]$s.SelectSingleNode('//tickManager/ticksGame').InnerText;zones=$zones;wood=$wood;pawns=$pawns;human_reservations=$reservations}|ConvertTo-Json -Depth 14
